### technical validation of Co-Phasing
# we generate 10 co-phased allele-specific chromatin contact maps from a subsampled F123 genome
# we compare those to the allele-specific chromatin contact maps generated by reads overlapping all known F123 SNPs (no co-phasing, no subsampling)
# UPDATE 18.05.21 : subsample again with 1SNP every 2kb (see below)
################################################################################
### steps here in R:
# subsample F123 to human SNP density (10 times)
# for each subsampled genome, generate seed SNPs files for each GAM sample
################################################################################
################################################################################
##### subsampling F123 #########################################################
################################################################################
################################################################################
# F123 SNPs are filtered for mininum mappability of 1, 
# load truth
full_SNPs_mm10 = readRDS('/fast/groups/ag_schwarz/Projects/project-gam/prelim/clean_mm10_gt_merged_mappability_minmap1.rds')
nrow(full_SNPs_mm10)
# 18150228

# check SNP density here again:
# split into chromosomes, calc distance
SNPs_mm10_chr = split(full_SNPs_mm10, full_SNPs_mm10$CHROM)
mm10_SNP_dist=unlist(lapply(SNPs_mm10_chr,function(chr){
    dist=diff(chr$POS)
}))
mean(mm10_SNP_dist) # 132.3968
median(mm10_SNP_dist) # 56

# check distribution of SNPs on CAST and J129 alleles:
table(full_SNPs_mm10$F123_GT)/nrow(full_SNPs_mm10)
#       0|1       1|0
# 0.1288906 0.8711094

# check again the SNP density by just seeing how many SNPs we have for how many basepairs in the genome:
# mouse genome is how long?
chromsize_mm10=read.table('/fast/groups/ag_schwarz/Projects/project-gam/RNAseq/data/Rieke_current/genome/chromsize.tsv',header = T)
sum(chromsize_mm10$size)/nrow(full_SNPs_mm10)
# 135.6867
# almost the same as the calculated distance above

# now we want to lower the SNP density to ~ 1 SNP every 1000bp (1kb), means we need x number of SNPs for the mouse genome length
nr_subsampled_SNPs = sum(chromsize_mm10$size)/1000 #[1] 2462745
nr_subsampled_SNPs/nrow(full_SNPs_mm10)*100 # 13.56867 % 

# I will sample indizes of the rows, so I can easily subset the SNP df
subsampled_F123_list = vector(mode = "list", length = 10)
for(seed in 1:10){
    set.seed(seed)
    SNPs_mm10_subsampled_indizes = sample(x = nrow(full_SNPs_mm10), size = nr_subsampled_SNPs, replace = FALSE)
    SNPs_mm10_subsampled = full_SNPs_mm10[sort(SNPs_mm10_subsampled_indizes),]
    subsampled_F123_list[[seed]] = SNPs_mm10_subsampled
    print(nrow(SNPs_mm10_subsampled)/nrow(full_SNPs_mm10)*100)
    print(table(SNPs_mm10_subsampled$F123_GT)/nrow(SNPs_mm10_subsampled))
    SNPs_mm10_subsampled_chr = split(SNPs_mm10_subsampled, SNPs_mm10_subsampled$CHROM)
    mm10_SNP_subsampled_dist=unlist(lapply(SNPs_mm10_subsampled_chr,function(chr){
        dist=diff(chr$POS)
    }))
    print(mean(mm10_SNP_subsampled_dist))
    print(median(mm10_SNP_subsampled_dist))
}

