subsampled_F123_list=readRDS('/fast/groups/ag_schwarz/Projects/project-gam/Co-Phasing/prelim/subsampled_F123/F123_mm10_GT_subsampled_to_human_SNPdensity_10times.rds')

# libraries
library(GAMIBHEAR)
library(stringr)
library(data.table)

chrom_order=paste("chr",c(1:19),sep="")

# load the F123 mpileup VCFs again, to be sure the correct samples are assigned to the correct filenames
vcf_dir = '/fast/groups/ag_schwarz/Projects/project-gam/data/F123_bam_files_1123_1NP_mm10_Sept_2019_last_base_trimmed_mpileup'
files = list.files(path = vcf_dir, pattern = '*.mpileup.vcf$')
VCF_list = load_sample_VCF(files,vcf_dir)
#processed_SNVs = process_sample_VCF(VCF_list)
processed_SNVs=readRDS("/fast/groups/ag_schwarz/Projects/project-gam/Co-Phasing/prelim/subsampled_F123/processed_F123_SNPs.rds")


# merge the SNPs with the 10 subsampled F123 genomes
processed_SNVs_merged_subsampled = lapply(subsampled_F123_list,function(i){
    obs_truth_merged = merge(processed_SNVs,i,by=c("CHROM","POS"))
    obs_truth_merged = obs_truth_merged[order(as.numeric(obs_truth_merged$POS)),]
    obs_truth_merged = obs_truth_merged[order(match(obs_truth_merged$CHROM,chrom_order)),]
    return(obs_truth_merged)
})

# i=subsampled_F123_list[[1]]
# dim(i) #[1] 2462745       9
# dim(processed_SNVs) #[1] 35879529        7
# dim(obs_truth_merged) #[1] 4739948      14
# dim(obs_truth_merged[!duplicated(obs_truth_merged[c("CHROM","POS")]),]) #[1] 1592473      14
# # I think that is ok. there are SNPs being observed in multiple samples, so more rows than the unique subsampled truth, but many observations are discarded due to the subsampled truth and not all SNPs from the subsa,pled truth are observed 


SNP_seed_beds_base = lapply(processed_SNVs_merged_subsampled,function(obs_truth_merged){
    obs_truth_merged$CASTcount=0
    obs_truth_merged$J129count=0
    obs_truth_merged$CASTcount[which(obs_truth_merged$F123_GT=='1|0')]=obs_truth_merged$ALT_COUNT[which(obs_truth_merged$F123_GT=='1|0')]
    obs_truth_merged$CASTcount[which(obs_truth_merged$F123_GT=='0|1')]=obs_truth_merged$REF_COUNT[which(obs_truth_merged$F123_GT=='0|1')]
    obs_truth_merged$J129count[which(obs_truth_merged$F123_GT=='1|0')]=obs_truth_merged$REF_COUNT[which(obs_truth_merged$F123_GT=='1|0')]
    obs_truth_merged$J129count[which(obs_truth_merged$F123_GT=='0|1')]=obs_truth_merged$ALT_COUNT[which(obs_truth_merged$F123_GT=='0|1')]
    obs_truth_merged$START = obs_truth_merged$POS-1
    obs_truth_merged$PARENT = c("CAST","J129")[apply(obs_truth_merged[,c("CASTcount","J129count")],1,which.max)]
    SNP_seed_beds=obs_truth_merged[,c('CHROM','START','POS','F123_GT','PARENT','SAMPLE')]
    
    return(SNP_seed_beds)
})
saveRDS(SNP_seed_beds_base,'/fast/groups/ag_schwarz/Projects/project-gam/Co-Phasing/prelim/subsampled_F123/F123_mm10_GT_subsampled_to_human_SNPdensity_10times_Snpseeds.rds')

# now write them out, in 10 different directories
samples_sort = unique(processed_SNVs$SAMPLE)[order(as.numeric(substring(unique(processed_SNVs$SAMPLE), 7)))] # e.g. 'sample7'


#for(i in 1:length(SNP_seed_beds_base)){print(length(unique(SNP_seed_beds_base[[i]]$SAMPLE)))} # all 1123

for(i in 1:length(SNP_seed_beds_base)){
    outfilenames=sub('\\.vcf$', paste('.closest_SNP_seed_subsampled_F123_',i,'.bed',sep=''), files)
    outdir=paste('/fast/groups/ag_schwarz/Projects/project-gam/Co-Phasing/prelim/subsampled_F123/closest_SNP_seed_files_subsampled_',i,sep='')
    SNP_seed_beds_base_iter=SNP_seed_beds_base[[i]]

    for (j in 1:length(files)){
        print(paste(i,': ',j,' / ', length(files)))
        sample_seed_SNPs=SNP_seed_beds_base_iter[which(SNP_seed_beds_base_iter$SAMPLE==samples_sort[j]),]
        if(nrow(sample_seed_SNPs)>0){
            write.table(sample_seed_SNPs,paste(outdir,outfilenames[j],sep = '/'),
                        sep = '\t',
                        quote = F,
                        row.names = F,
                        col.names = F)
        }else{print("emtpy")}
    }
}


