SNP_seed_beds_base = lapply(processed_SNVs_merged_subsampled,function(obs_truth_merged){
    obs_truth_merged$CASTcount=0
    obs_truth_merged$J129count=0
    obs_truth_merged$CASTcount[which(obs_truth_merged$F123_GT=='1|0')]=obs_truth_merged$ALT_COUNT[which(obs_truth_merged$F123_GT=='1|0')]
    obs_truth_merged$CASTcount[which(obs_truth_merged$F123_GT=='0|1')]=obs_truth_merged$REF_COUNT[which(obs_truth_merged$F123_GT=='0|1')]
    obs_truth_merged$J129count[which(obs_truth_merged$F123_GT=='1|0')]=obs_truth_merged$REF_COUNT[which(obs_truth_merged$F123_GT=='1|0')]
    obs_truth_merged$J129count[which(obs_truth_merged$F123_GT=='0|1')]=obs_truth_merged$ALT_COUNT[which(obs_truth_merged$F123_GT=='0|1')]
    obs_truth_merged$START = obs_truth_merged$POS-1
    obs_truth_merged$PARENT = c("CAST","J129")[apply(obs_truth_merged[,c("CASTcount","J129count")],1,which.max)]
    SNP_seed_beds=obs_truth_merged[,c('CHROM','START','POS','F123_GT','PARENT','SAMPLE')]
    
    return(SNP_seed_beds)
})
saveRDS(SNP_seed_beds_base,'/fast/groups/ag_schwarz/Projects/project-gam/Co-Phasing/prelim/subsampled_F123/F123_3NPs_mm10_GT_subsampled_to_human_SNPdensity_10times_Snpseeds.rds')

